using System.IO;
using System.Security.Cryptography;
using System.Text.Json;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Collections.ObjectModel;
using RAWSelectionAssistant.Core.Services.Color;
using RAWSelectionAssistant.Core.Services.Projects;
using RAWSelectionAssistant.Core.Services.RawToJpeg;
static class Program {
 static string Hash(byte[] b)=>Convert.ToHexString(SHA256.HashData(b));
 [STAThread]static int Main(string[]a){if(a.Length!=2)return 2;var plan=JsonDocument.Parse(File.ReadAllText(a[0])).RootElement;var root=a[1];if(Directory.Exists(root))throw new IOException("Preserve crops");Directory.CreateDirectory(root);var pipeline=new RawMatchTiff16ProductPipeline(new LibRawDecoder());var profile=new ColorContext(PixelFormats.Bgra32);byte[] icc;using(var s=profile.OpenProfileStream()){using var m=new MemoryStream();s.CopyTo(m);icc=m.ToArray();}File.WriteAllBytes(Path.Combine(root,"product-srgb.icc"),icc);
 // Pixel-local neutral render: cropping first must match a region of the full rendered synthetic image.
 var synthetic=Enumerable.Range(0,32*24*3).Select(i=>(ushort)(i*17%65536)).ToArray();using(var full=new HighBitDepthImageBuffer(32,24,synthetic)){using var rendered=pipeline.Render(full,null,null).ProcessingPixels!;var crop=new ushort[8*8*3];for(int y=0;y<8;y++)Array.Copy(synthetic,((y+4)*32+5)*3,crop,y*24,24);using var input=new HighBitDepthImageBuffer(8,8,crop);using var partial=pipeline.Render(input,null,null).ProcessingPixels!;var expected=rendered.ToRgb48();var actual=partial.ToRgb48();for(int y=0;y<8;y++)if(!expected.AsSpan(((y+4)*32+5)*3,24).SequenceEqual(actual.AsSpan(y*24,24)))throw new InvalidDataException("Neutral crop/full render mismatch");}
 var receipts=new List<object>();foreach(var input in plan.GetProperty("inputs").EnumerateArray()){var source=input.GetProperty("path").GetString()!;using(var verify=File.OpenRead(source))if(Convert.ToHexString(SHA256.HashData(verify)).ToLowerInvariant()!=input.GetProperty("sha256").GetString())throw new InvalidDataException("Stored finished-input SHA");var imageWidth=input.GetProperty("width").GetInt32();foreach(var roi in plan.GetProperty("rois").EnumerateArray()){var x=roi.GetProperty("x").GetInt32();var y=roi.GetProperty("y").GetInt32();var w=roi.GetProperty("width").GetInt32();var h=roi.GetProperty("height").GetInt32();var values=new ushort[w*h*3];var row=new byte[w*6];using(var f=File.OpenRead(source))for(int yy=0;yy<h;yy++){f.Position=((long)(y+yy)*imageWidth+x)*6;f.ReadExactly(row);Buffer.BlockCopy(row,0,values,yy*row.Length,row.Length);}using var master=new HighBitDepthImageBuffer(w,h,values,"16","sRGB",1);using var output=pipeline.Render(master,null,null).ProcessingPixels!;var data=output.ToRgb48();var raw=new byte[data.Length*2];Buffer.BlockCopy(data,0,raw,0,raw.Length);var visual=output.ToVisualRgb24().Rgb24.ToArray();var name=roi.GetProperty("name").GetString()+"-"+input.GetProperty("label").GetString();Save(Path.Combine(root,name+"-16.png"),w,h,PixelFormats.Rgb48,raw,w*6,profile);Save(Path.Combine(root,name+"-8.png"),w,h,PixelFormats.Rgb24,visual,w*3,profile);File.WriteAllBytes(Path.Combine(root,name+".rgb48"),raw);receipts.Add(new{name,inputLabel=input.GetProperty("label").GetString(),x,y,width=w,height=h,renderedRgb16Sha=Hash(raw),displayRgb8Sha=Hash(visual),iccSha=Hash(icc),sourceSha=input.GetProperty("sha256").GetString(),renderer=typeof(RawMatchTiff16ProductPipeline).FullName,recipe="look=null stack=null film=null orientation1 maximumEdge0"});}}
 File.WriteAllText(Path.Combine(root,"CROP_RECEIPT.json"),JsonSerializer.Serialize(new{status="PASS_FIXED_STORED_INPUT_CROPS",syntheticNeutralCropEquivalence=true,rawDecoderCalls=0,iccSha=Hash(icc),receipts},new JsonSerializerOptions{WriteIndented=true}));return 0;
 }
 static void Save(string p,int w,int h,PixelFormat format,byte[] data,int stride,ColorContext profile){var bmp=BitmapSource.Create(w,h,96,96,format,null,data,stride);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bmp,null,null,new ReadOnlyCollection<ColorContext>([profile])));using(var f=new FileStream(p,FileMode.CreateNew))encoder.Save(f);using var source=File.OpenRead(p);var decoded=BitmapDecoder.Create(source,BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad).Frames[0];if(decoded.PixelWidth!=w||decoded.PixelHeight!=h||decoded.Format.BitsPerPixel!=format.BitsPerPixel||decoded.ColorContexts?.Count!=1)throw new InvalidDataException("PNG depth/profile contract");var check=new byte[data.Length];BitmapSource canonical=decoded.Format==format?decoded:new FormatConvertedBitmap(decoded,format,null,0);canonical.CopyPixels(check,stride,0);if(!check.AsSpan().SequenceEqual(data)){File.WriteAllBytes(p+".expected",data);File.WriteAllBytes(p+".decoded",check);File.WriteAllText(p+".format",decoded.Format.ToString());throw new InvalidDataException("Encoded crop pixel mismatch");}}
}
